/**
 * Generated by: adlc-framework/.claude/plugins/commerce/scripts/autotest.sh
 * Flow: promotions
 * Scope: commerce-autonomous-test-authoring
 *
 * DETERMINISTIC SPEC — no LLM/MCP/agent imports. Plain Playwright.
 *
 * Flow: buyer navigates to cart → looks for promo code input
 *       assert promo section is visible + total might show discount applied
 */

import path from "node:path";
import { test, expect } from "../fixtures/auth";
import {
  STOREFRONT_URL,
  SCREENSHOTS_DIR,
  TEST_REGION_COUNTRY,
} from "../config";

test.describe("B2B promotions flow [generated]", () => {
  test("buyer sees promotion code section and cart totals", async ({
    buyerPage,
  }) => {
    // Step 1: navigate to cart
    await buyerPage.goto(`${STOREFRONT_URL}/${TEST_REGION_COUNTRY}/cart`);
    await buyerPage.waitForLoadState("networkidle");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-promotions-01-cart.png"),
    });

    // Step 2: HARD assertion — promo code input or section is visible
    const promoSection = buyerPage.locator('[data-testid="promotion-code"]')
      .or(buyerPage.locator('input[placeholder*="Promo"], input[placeholder*="Code"]').first())
      .or(buyerPage.locator('text=/promo|Promo Code|coupon/i').first());

    await expect(promoSection).toBeVisible({ timeout: 5000 });
    console.log("[promotions] HARD ASSERT 1 PASS: Promo section visible");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-promotions-02-promo-input.png"),
    });

    // Step 3: HARD assertion — cart total is visible (content-check value)
    const cartTotalLocator = buyerPage.locator('[data-testid="cart-total"]')
      .or(buyerPage.locator('text=/Total:?|Total|total/i').first());

    await expect(cartTotalLocator.first()).toBeVisible({ timeout: 5000 });
    const totalText = await cartTotalLocator.first().textContent();
    console.log(`[promotions] CONTENT CHECK: Cart total = "${totalText}"`);

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-promotions-03-cart-total.png"),
    });

    console.log("[promotions] Flow complete — hard asserts + content checks passed");
  });
});
